                "会话上限": session_limit,
                "超限": exceed,
            }
            for template_id, rate, burst, quota, session_limit, exceed in templates
        ],
        "用户模板": [
            [user, template_id] for user, template_id in user_templates
        ],
        "容量": {
            "队列上限": queue_limit,
            "最大等待毫秒": max_wait_ms,
        },
        "认证": {
